package com.food.entity;
import java.util.*; import jakarta.persistence.*;
@Entity @Table(name="restaurants") public class Restaurant { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private int id; @Column(nullable=false) private String name; private String city; private double rating; @OneToMany(mappedBy="restaurant",cascade=CascadeType.ALL,fetch=FetchType.EAGER) private List<MenuItem> menuItems=new ArrayList<>(); public Restaurant(){} public Restaurant(String name,String city,double rating){this.name=name;this.city=city;this.rating=rating;} public int getId(){return id;} public void setId(int id){this.id=id;} public String getName(){return name;} public void setName(String name){this.name=name;} public String getCity(){return city;} public void setCity(String city){this.city=city;} public double getRating(){return rating;} public void setRating(double rating){this.rating=rating;} public List<MenuItem> getMenuItems(){return menuItems;} public void setMenuItems(List<MenuItem> m){menuItems=m;} }
